function notify(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function setView(view){$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#matchView').classList.toggle('active-view',view==='match');$('#contentView').classList.toggle('active-view',view!=='match');$('#topContext').textContent=view==='table'?'LEAGUE TABLE':view.toUpperCase();if(view!=='match')renderPage(view);}
