function applyOpponent(){const t=opponent();$('#awayShort').textContent=t.short;$('#awayLabel').innerHTML=`${t.name.toUpperCase()} FC <i>${['4-2-3-1','4-3-3','3-4-2-1'][state.round%3]}</i>`;$('#fixtureAway').textContent=t.short;$('#fixtureAwayCrest').textContent=t.crest;$('#fixtureAwayCrest').style.backgroundColor='#'+t.color.toString(16).padStart(6,'0');$('#fixtureNumber').textContent=String(state.round+1).padStart(2,'0');$('#roundLabel').textContent=`${String(state.round+1).padStart(2,'0')} / 38`;$('#seasonBar').style.width=`${Math.max(3,(state.round/38)*100)}%`;}
function refreshMatchUI(){const m=state;$('#homeScore').textContent=m.homeScore;$('#awayScore').textContent=m.awayScore;$('#matchClock').textContent=`${String(Math.floor(m.clock)).padStart(2,'0')}:${m.running?'00':'00'}`;$('#homeShots').textContent=m.shots[0];$('#awayShots').textContent=m.shots[1];$('#homeOn').textContent=m.on[0];$('#awayOn').textContent=m.on[1];$('#homeCorners').textContent=m.corners[0];$('#awayCorners').textContent=m.corners[1];$('#homePoss').textContent=`${m.possession}%`;$('#awayPoss').textContent=`${100-m.possession}%`;$('#homeMomentum').style.width=`${m.possession}%`;$('#awayMomentum').style.width=`${100-m.possession}%`;$('#eventCount').textContent=`${m.events.length} EVENT${m.events.length===1?'':'S'}`;$('#matchStateText').textContent=m.ended?'FULL TIME':m.running?'MATCH IN PLAY':'KICK OFF IN';$('#matchStatus').textContent=m.ended?'FULL TIME':m.running?'LIVE':'UP NEXT';$('.live-pill').classList.toggle('is-live',m.running);$('.clock-chip').classList.toggle('is-running',m.running);const play=$('#playButton');play.innerHTML=m.running?'<span>Ⅱ</span> <b>PAUSE MATCH</b>':m.ended?'<span>↻</span> <b>NEXT MATCH</b>':'<span>▶</span> <b>START MATCH</b>';play.classList.toggle('running',m.running);$('#simButton').textContent=m.ended?'SEASON HUB  ↗':'SIMULATE  ↗';renderEvents();}
function addEvent(minute,text,detail='',type=''){const event={minute,text,detail,type,id:Date.now()+Math.random()};state.events.unshift(event);if(state.events.length>9)state.events.pop();renderEvents();$('#eventCount').textContent=`${state.events.length} EVENT${state.events.length===1?'':'S'}`;}
function renderEvents(){const list=$('#eventList');if(!state.events.length){list.innerHTML='<div class="empty-event"><span>◷</span><div><strong>It\'s almost time.</strong><small>The tunnel is buzzing. Make your final call.</small></div></div>';return;}list.innerHTML=state.events.map(e=>`<div class="event-row ${e.type}"><span class="event-time">${String(e.minute).padStart(2,'0')}'</span><span class="event-symbol">${e.type==='goal'?'⚽':e.type==='chance'?'◉':'↗'}</span><div class="event-text"><strong>${e.text}</strong><small>${e.detail}</small></div></div>`).join('');}
