$$('.speed-btn').forEach(b=>b.addEventListener('click',()=>{$$('.speed-btn').forEach(x=>x.classList.toggle('active',x===b));state.speed=Number(b.dataset.speed);notify(`Match speed set to ${state.speed}×`)}));
