function startMatch(){if(state.ended)return;state.running=true;if(state.clock===0){addEvent(0,'The referee blows the whistle','We are underway at North London Stadium.');notify('KICK OFF — make it count');}refreshMatchUI();if(timer)clearInterval(timer);timer=setInterval(matchStep,1000);}
function pauseMatch(){state.running=false;clearInterval(timer);refreshMatchUI();notify('Match paused');}
function matchStep(){state.clock=Math.min(90,state.clock+state.speed);if(state.clock===45){addEvent(45,'Half-time','A chance to reset and make a change.');notify('HALF-TIME — regroup for the second half');}if(Math.random()<.17*state.speed&&state.clock<90)createChance();refreshMatchUI();if(state.clock>=90)finishMatch();}
function createChance(){const opp=opponent(),homeAtt=state.tactic==='pressing'?.61:state.tactic==='counter'?.53:.54;const homeChance=Math.random()<homeAtt;const side=homeChance?0:1;const player=homeChance?squad[Math.floor(Math.random()*3)].name:`${['J. Palmer','M. Salah','A. Gordon','B. Silva'][Math.floor(Math.random()*4)]}`;state.shots[side]++;const goalProb=homeChance?Math.max(.12,.27+(clubPower()-opp.power)*.012+(state.tactic==='pressing'?.04:state.tactic==='counter'?.06:0)):Math.max(.1,.26+(opp.power-clubPower())*.01);const goal=Math.random()<goalProb;if(goal){if(homeChance)state.homeScore++;else state.awayScore++;state.on[side]++;addEvent(state.clock,`GOAL! ${player}`,homeChance?'A brilliant finish — the home end erupts.':`The visitors find the net. ${player} scores for ${opp.name}.`,'goal');showMatchToast(homeChance?'GOAL! NORTH LONDON FC':'GOAL! '+opp.short);window.animateBall?.(homeChance?1:-1);}else{if(Math.random()<.46)state.on[side]++;addEvent(state.clock,`${player} goes close`,homeChance?'A sharp effort, but the keeper is equal to it.':`${opp.name} threaten, but the chance goes begging.`,'chance');window.animateBall?.(homeChance?.7:-.7);}state.possession=Math.max(35,Math.min(65,Math.round(50+(clubPower()-opp.power)*.4+(state.tactic==='pressing'?4:state.tactic==='counter'?-4:0)+(Math.random()*12-6))));if(Math.random()<.18)state.corners[side]++;}
function showMatchToast(msg){const el=$('#matchToast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800);}
function finishMatch(){clearInterval(timer);state.running=false;state.ended=true;state.clock=90;const t=state.table.find(x=>x.name==='North London FC'),opp=state.table.find(x=>x.name===opponent().name);t.gf+=state.homeScore;t.ga+=state.awayScore;opp.gf+=state.awayScore;opp.ga+=state.homeScore;if(state.homeScore>state.awayScore){t.w++;t.pts+=3;opp.l++;}else if(state.homeScore<state.awayScore){opp.w++;opp.pts+=3;t.l++;}else{t.d++;opp.d++;t.pts++;opp.pts++;}addEvent(90,'Full-time',`${state.homeScore}–${state.awayScore} against ${opponent().name}.`);refreshMatchUI();showMatchToast('FULL TIME');notify(`FULL TIME — ${state.homeScore}–${state.awayScore}`);}
function simulateMatch(){if(state.running)pauseMatch();if(state.ended){setView('table');return;}state.clock=90;const opp=opponent();const homeStrength=clubPower()+(state.tactic==='pressing'?2:state.tactic==='counter'?1:0);const homeGoals=Math.max(0,poisson(1.25+(homeStrength-opp.power)*.055));const awayGoals=Math.max(0,poisson(1.15+(opp.power-homeStrength)*.045));state.homeScore=homeGoals;state.awayScore=awayGoals;state.shots=[6+Math.floor(Math.random()*9),5+Math.floor(Math.random()*9)];state.on=[Math.min(homeGoals+2,Math.floor(state.shots[0]*.45)),Math.min(awayGoals+2,Math.floor(state.shots[1]*.4))];state.corners=[Math.floor(Math.random()*7),Math.floor(Math.random()*6)];state.possession=48+Math.floor(Math.random()*12);addEvent(0,'Match simulated','Your tactical plan played out over 90 minutes.');if(homeGoals)addEvent(90,`${homeGoals} goal${homeGoals>1?'s':''} for North London FC`,'The home side found the net.','goal');finishMatch();}
function poisson(lambda){let L=Math.exp(-Math.max(.15,lambda)),k=0,p=1;do{k++;p*=Math.random();}while(p>L);return k-1;}
function nextMatch(){state.round++;if(state.round>=38){notify('SEASON COMPLETE — congratulations, boss!');state.round=0;}state.homeScore=0;state.awayScore=0;state.clock=0;state.running=false;state.ended=false;state.possession=50;state.shots=[0,0];state.on=[0,0];state.corners=[0,0];state.events=[];matchCounter++;applyOpponent();refreshMatchUI();setView('match');window.resetMatchScene?.();notify(`FIXTURE ${state.round+1} — prepare for ${opponent().name}`);}

