const grass=new T.Mesh(new T.PlaneGeometry(105,68),new T.MeshStandardMaterial({color:0x2d6838,roughness:.98}));grass.rotation.x=-Math.PI/2;grass.position.y=.12;grass.receiveShadow=true;scene.add(grass);
for(let i=0;i<10;i++){const stripe=new T.Mesh(new T.PlaneGeometry(10.5,68),new T.MeshStandardMaterial({color:i%2?0x2d6838:0x326f3d,roughness:1}));stripe.rotation.x=-Math.PI/2;stripe.position.set(-47.25+i*10.5,.14,0);scene.add(stripe);}
const lineMat=new T.LineBasicMaterial({color:0xd9ead2,transparent:true,opacity:.77});function line(points,closed=false){const pts=points.map(p=>new T.Vector3(p[0],.25,p[1]));const g=new T.BufferGeometry().setFromPoints(pts);const l=closed?new T.LineLoop(g,lineMat):new T.Line(g,lineMat);scene.add(l);return l;}function circle(cx,cz,r){const pts=[];for(let i=0;i<=72;i++){const a=i/72*Math.PI*2;pts.push([cx+Math.cos(a)*r,cz+Math.sin(a)*r]);}line(pts);}
line([[-52.5,-34],[52.5,-34],[52.5,34],[-52.5,34]],true);line([[0,-34],[0,34]]);circle(0,0,9.15);const spotGeo=new T.CircleGeometry(.35,20);const spotMat=new T.MeshBasicMaterial({color:0xe8f2d9});const spot=new T.Mesh(spotGeo,spotMat);spot.rotation.x=-Math.PI/2;spot.position.set(0,.27,0);scene.add(spot);
for(const side of [-1,1]){const z=side*34;line([[-20,z],[20,z],[20,z-side*16.5],[-20,z-side*16.5]],true);line([[-9.2,z],[9.2,z],[9.2,z-side*5.5],[-9.2,z-side*5.5]],true);const goalMat=new T.MeshStandardMaterial({color:0xdce9dc,roughness:.55});for(const x of [-3.65,3.65]){const post=new T.Mesh(new T.CylinderGeometry(.13,.13,2.45,8),goalMat);post.position.set(x,1.3,z+side*2.7);scene.add(post);}const bar=new T.Mesh(new T.BoxGeometry(7.4,.15,.15),goalMat);bar.position.set(0,2.5,z+side*2.7);scene.add(bar);const net=new T.Mesh(new T.BoxGeometry(7.3,2.3,5.2),new T.MeshBasicMaterial({color:0xffffff,wireframe:true,transparent:true,opacity:.15}));net.position.set(0,1.2,z+side*5.1);scene.add(net);}
