 function renderTactics(root){const pos=state.formation==='4-2-3-1'?[[50,89],[17,70],[39,73],[61,73],[83,70],[37,53],[63,53],[19,31],[50,32],[81,31],[50,13]]:state.formation==='3-5-2'?[[50,89],[28,73],[50,75],[72,73],[12,51],[32,52],[50,55],[68,52],[88,51],[39,29],[61,29]]:[[50,89],[16,70],[39,73],[61,73],[84,70],[31,51],[50,54],[69,51],[19,28],[50,25],[81,28]];const starting=[squad[10],squad[6],squad[7],squad[8],squad[9],squad[3],squad[4],squad[5],squad[2],squad[0],squad[1]];root.innerHTML=`<div class="content-page">${pageHeader('MATCH PREPARATION · GAME PLAN','SET THE SHAPE.','Every match is won before the whistle.')}
 <div class="content-grid"><div class="content-panel"><h2>Formation & positioning</h2><p class="subcopy">Choose your shape, then take the game to them.</p><select class="formation-select" id="formationSelect"><option ${state.formation==='4-3-3'?'selected':''}>4-3-3</option><option ${state.formation==='4-2-3-1'?'selected':''}>4-2-3-1</option><option ${state.formation==='3-5-2'?'selected':''}>3-5-2</option></select><div class="formation-board">${starting.map((p,i)=>`<div class="formation-player" style="left:${pos[i][0]}%;top:${pos[i][1]}%"><div class="shirt-token">${p.number}</div><span>${p.name.split(' ').pop()}</span></div>`).join('')}</div></div><div><div class="content-panel"><h2>Match approach</h2><p class="subcopy">Select your team's identity.</p>${[['balanced','◈','Balanced','Keep shape and control tempo'],['pressing','↗','High press','Hunt the ball high up the pitch'],['counter','⌁','Counter attack','Stay compact and break quickly']].map(([key,icon,name,desc])=>`<button class="tactic-option ${state.tactic===key?'selected':''}" data-tactic="${key}" style="width:100%"><span class="tactic-icon">${icon}</span><span><strong>${name}</strong><small>${desc}</small></span><i class="radio-dot"></i></button>`).join('')}<div class="stat-line"><span>Attack intensity</span><strong class="green">${state.tactic==='pressing'?'HIGH':state.tactic==='counter'?'MEDIUM':'BALANCED'}</strong></div><div class="stat-line"><span>Team rating</span><strong>${clubPower()} / 100</strong></div></div><div class="content-message">Your current game plan: <strong>${state.tactic==='balanced'?'Balanced control':state.tactic==='pressing'?'High press':'Counter attack'}</strong>. You can make changes right up until kick-off.</div></div></div></div>`;$('#formationSelect').addEventListener('change',e=>{state.formation=e.target.value;$('#formationQuick').innerHTML=`${state.formation} <i>⌄</i>`;renderTactics(root);notify(`Formation changed to ${state.formation}`)});$$('[data-tactic]').forEach(b=>b.addEventListener('click',()=>{setTactic(b.dataset.tactic);renderTactics(root);notify(`Tactical approach: ${b.querySelector('strong').textContent}`)}));}
-function renderTable(root){const table=[...state.table].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga));const us={name:'North London FC',short:'NTH',crest:'N',power:clubPower(),pts:state.table.find(t=>t.name==='North London FC')?.pts||0,w:state.table.find(t=>t.name==='North London FC')?.w||0,d:state.table.find(t=>t.name==='North London FC')?.d||0,l:state.table.find(t=>t.name==='North London FC')?.l||0,gf:state.table.find(t=>t.name==='North London FC')?.gf||0,ga:state.table.find(t=>t.name==='North London FC')?.ga||0};table.push(us);table.sort((a,b)=>b.pts-a.pts||((b.gf-b.ga)-(a.gf-a.ga)));root.innerHTML=`<div class="content-page">${pageHeader(`PREMIER LEAGUE · ${state.round?`AFTER MATCHDAY ${state.round}`:'BEFORE MATCHDAY 1'}`,'THE TABLE.','38 games. One champion. This is where your season stands.')}
+function renderTable(root){const table=[...state.table].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga));root.innerHTML=`<div class="content-page">${pageHeader(`PREMIER LEAGUE · ${state.round?`AFTER MATCHDAY ${state.round}`:'BEFORE MATCHDAY 1'}`,'THE TABLE.','38 games. One champion. This is where your season stands.')}
 <div class="content-panel"><table class="table-list"><thead><tr><th>POS</th><th>CLUB</th><th>PL</th><th>W</th><th>D</th><th>L</th><th>GD</th><th>PTS</th><th>FORM</th></tr></thead><tbody>${table.map((t,i)=>`<tr class="${t.name==='North London FC'?'your-team':''}"><td>${String(i+1).padStart(2,'0')}</td><td>${t.name==='North London FC'?'◆':t.crest||t.name[0]} &nbsp;${t.name}</td><td>${t.w+t.d+t.l}</td><td>${t.w}</td><td>${t.d}</td><td>${t.l}</td><td>${t.gf-t.ga>0?'+':''}${t.gf-t.ga}</td><td><strong>${t.pts}</strong></td><td class="form-small">${t.name==='North London FC'?(state.round?'W · D · W':'—'):i<3?'W · W · D':'—'}</td></tr>`).join('')}</tbody></table></div></div>`;}
 function renderTraining(root){const drills=[['attack','⚽','Attacking patterns','Improve forward movement and finishing','M. Rivera · A. Johnson'],['fitness','↗','Conditioning','Boost fitness and match intensity','Whole squad'],['defence','⬟','Defensive shape','Work on organisation and clean sheets','Back four']];root.innerHTML=`<div class="content-page">${pageHeader('TRAINING GROUND · WEEK ${Math.max(1,state.round)}','PUT IN THE WORK.','A great team is built between matchdays.')}
 <div class="content-grid"><div class="content-panel"><h2>Choose a training focus</h2><p class="subcopy">Training takes one week. Each drill improves your match readiness.</p>${drills.map(([key,icon,title,desc,target])=>`<div class="training-card"><div class="train-icon">${icon}</div><div class="training-info"><div><h3>${title}</h3><p>${desc} · ${target}</p></div></div><button class="train-btn" data-train="${key}" ${state.trained[key]?'disabled':''}>${state.trained[key]?'COMPLETED ✓':'START SESSION'}</button></div>`).join('')}</div><div><div class="content-panel"><h2>Training status</h2><p class="subcopy">This week's preparation.</p><div class="stat-line"><span>Team sharpness</span><strong class="green">${state.trained.attack||state.trained.defence?'86%':'78%'}</strong></div><div class="stat-line"><span>Player condition</span><strong>94%</strong></div><div class="stat-line"><span>Sessions completed</span><strong>${Object.keys(state.trained).length} / 3</strong></div><div class="stat-line"><span>Next match</span><strong>${opponent().short} · ${state.round+1}</strong></div></div><div class="content-message">Training bonuses last for the current fixture. Get a session in before the match to give your side an edge.</div></div></div></div>`;$$('[data-train]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.train;if(state.trained[key])return;state.trained[key]=key==='attack'?2:key==='fitness'?1:1;state.morale=Math.min(99,state.morale+2);const label=drills.find(d=>d[0]===key)[2];notify(`${label} complete — your squad is sharper`);renderTraining(root);}));}

