const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,args:['--no-sandbox','--enable-unsafe-swiftshader']});
 const page=await browser.newPage({viewport:{width:1280,height:850},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
 await page.goto('http://127.0.0.1:4173',{waitUntil:'networkidle',timeout:45000});
 await page.waitForTimeout(1000);
 const startup={status:await page.locator('#matchStatus').innerText(),canvas:await page.locator('#pitch3d canvas').count()};
 await page.locator('[data-view="table"]').click();
 const rows=await page.locator('.table-list tbody tr').count();
 const clubRows=await page.locator('.table-list tbody tr.your-team').count();
 await page.locator('[data-view="match"]').click();
 await page.locator('#simButton').click();
 await page.waitForTimeout(150);
 const match=await page.locator('#matchStatus').innerText();
 await page.locator('[data-view="table"]').click();
 const afterMatchRows=await page.locator('.table-list tbody tr').count();
 await page.locator('[data-view="match"]').click();
 await page.waitForTimeout(250);
 await page.screenshot({path:'/tmp/opencode/touchline-final.jpg',type:'jpeg',quality:68});
 console.log(JSON.stringify({startup,rows,clubRows,match,afterMatchRows,errors},null,2));
 await browser.close();
 if(rows!==20||clubRows!==1||afterMatchRows!==20||errors.length)process.exit(1);
})().catch(e=>{console.error(e);process.exit(1)});
